package com.nextgen.store.payment;
import com.fasterxml.jackson.databind.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.MessageDigest;
@RestController @RequestMapping("/api/v1/payments/webhooks") public class PaymentWebhookController {private final PaymentRepository payments;private final PaymentWebhookEventRepository events;private final ObjectMapper mapper;private final String secret;public PaymentWebhookController(PaymentRepository payments,PaymentWebhookEventRepository events,ObjectMapper mapper,@Value("${payment.razorpay.webhook-secret:}") String secret){this.payments=payments;this.events=events;this.mapper=mapper;this.secret=secret;}
 @PostMapping("/razorpay") @Transactional public ResponseEntity<Void> razorpay(@RequestHeader(value="X-Razorpay-Signature",required=false) String signature,@RequestHeader(value="x-razorpay-event-id",required=false) String eventId,@RequestBody String body){if(secret.isBlank()||signature==null||!validSignature(body,signature)||eventId==null||eventId.isBlank())return ResponseEntity.badRequest().build();try{if(events.existsByEventId(eventId))return ResponseEntity.ok().build();JsonNode root=mapper.readTree(body);String type=root.path("event").asText(null);PaymentStatus next=statusFor(type);if(next!=null){String paymentId=root.at("/payload/payment/entity/id").asText(null);String orderId=root.at("/payload/payment/entity/order_id").asText(null);if(orderId==null)orderId=root.at("/payload/order/entity/id").asText(null);java.util.Optional<Payment> match=paymentId==null?java.util.Optional.empty():payments.findByGatewayPaymentId(paymentId);if(match.isEmpty()&&orderId!=null)match=payments.findByGatewayOrderId(orderId);if(match.isPresent())apply(match.get(),next);}events.save(new PaymentWebhookEvent(eventId,type==null?"unknown":type));return ResponseEntity.ok().build();}catch(Exception e){return ResponseEntity.badRequest().build();}}
 private void apply(Payment p,PaymentStatus next){try{p.transitionTo(next);var o=p.getOrder();switch(next){case AUTHORIZED->o.setPaymentStatus("AUTHORIZED");case CAPTURED->{o.setPaymentStatus("CAPTURED");o.setStatus(com.nextgen.store.order.OrderStatus.CONFIRMED);}case FAILED->o.setPaymentStatus("FAILED");case REFUNDED->o.setPaymentStatus("REFUNDED");default->{}}}catch(IllegalStateException ignored){}}
 private PaymentStatus statusFor(String e){if(e==null)return null;return switch(e){case "payment.captured","order.paid"->PaymentStatus.CAPTURED;case "payment.authorized"->PaymentStatus.AUTHORIZED;case "payment.failed"->PaymentStatus.FAILED;case "refund.processed"->PaymentStatus.REFUNDED;default->null;};}
 private boolean validSignature(String body,String received){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));byte[] d=mac.doFinal(body.getBytes(StandardCharsets.UTF_8));StringBuilder h=new StringBuilder(d.length*2);for(byte b:d)h.append(String.format("%02x",b));return MessageDigest.isEqual(h.toString().getBytes(StandardCharsets.UTF_8),received.getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}}
}
